"""Wires, power symbols and net labels for placed parts.

A maze router on the sheet grid (Lee/A*), with the rules a schematic needs
on top of a board's:

- a wire never touches another net's pin end or another net's wire end or
  corner: in Altium a touch is a connection;
- it may cross another net's wire at a right angle, never run along it,
  and never turn on it (a corner there would join the two);
- it never runs through a part's body or along a pin;
- no four-way joins: a branch lands on a plain stretch of wire (a T).

Ground and supply pins go to power symbols. A pin may join the net's wire
already drawn or take its own symbol, whichever costs less, so nearby pins
share a symbol and far ones get their own instead of a wire across the
sheet. Every signal net is named once by a net label on a horizontal
stretch with room for the text.
"""
from __future__ import annotations

import heapq
import math
from dataclasses import dataclass, field
from typing import Optional

from .circuit import DIRS, DOWN, GRID, UP, Circuit
from .place import Cell, Layout

INF = float("inf")
_H, _V = 1, 2


@dataclass
class Costs:
    step: float = 1.0
    bend: float = 2.0
    off_pin_axis: float = 1.5      # leaving a pin sideways, not straight out
    cross: float = 25.0
    near_text: float = 3.0
    junction: float = 0.5
    junction_at_pin: float = 2.0
    port_ground: float = 2.5
    port_power: float = 10.0
    label_pin: float = 18.0        # a signal pin named by its own label, not wired
    label_stub: float = 6.0
    label_fallback: float = 40.0   # a connection the router gave up on


@dataclass
class Routed:
    wires: list[dict] = field(default_factory=list)
    ports: list[dict] = field(default_factory=list)
    labels: list[dict] = field(default_factory=list)
    cost: float = 0.0
    length: int = 0
    bends: int = 0
    crossings: int = 0
    fallbacks: list[str] = field(default_factory=list)


def _bit(d: int) -> int:
    return _H if d in (0, 2) else _V


class Router:
    def __init__(self, circuit: Circuit, layout: Layout, costs: Optional[Costs] = None,
                 margin: int = 8):
        self.c = circuit
        self.lay = layout
        self.k = costs or Costs()
        x0, y0, x1, y1 = layout.bounds
        self.bounds = (x0 - margin, y0 - margin, x1 + margin, y1 + margin)
        self.blocked: set[Cell] = set()
        self.soft: dict[Cell, float] = {}
        self.pin_at: dict[Cell, list[tuple[str, str, int, Optional[str]]]] = {}
        for p in layout.parts.values():
            self.blocked |= p.body | p.lines
            for q in p.text:
                self.soft[q] = self.k.near_text
            for pe in p.pins:
                net = circuit.pin_net.get((p.ref, pe.number))
                self.pin_at.setdefault((pe.x // GRID, pe.y // GRID), []).append(
                    (p.ref, pe.number, pe.orientation, net))
        self.owner: dict[Cell, str] = {}
        self.axis: dict[Cell, int] = {}
        self.links: dict[Cell, int] = {}
        self.vertex: set[Cell] = set()
        self.reserved: dict[Cell, str] = {}
        self.tree: dict[str, set[Cell]] = {}
        self.crossed: dict[str, set[Cell]] = {}
        self.named: dict[str, set[Cell]] = {}      # label points per net
        self.tangled: set[str] = set()             # nets in a crossing
        self.out = Routed()

    # --- the grid ----------------------------------------------------------

    def _inside(self, q: Cell) -> bool:
        x0, y0, x1, y1 = self.bounds
        return x0 <= q[0] <= x1 and y0 <= q[1] <= y1

    def _free(self, q: Cell) -> bool:
        """Nothing at all there: room for a symbol or a label's text."""
        return (self._inside(q) and q not in self.blocked and q not in self.pin_at
                and q not in self.owner and q not in self.reserved
                and q not in self.soft)

    def _enter(self, net: str, q: Cell, d: int) -> Optional[tuple[float, bool]]:
        """(extra cost, is a crossing) of stepping onto q moving d; None if barred."""
        if not self._inside(q) or q in self.blocked:
            return None
        if q in self.reserved:          # a symbol or a label's text: no wire at all
            return None
        pins = self.pin_at.get(q)
        if pins:
            if any(p[3] != net for p in pins):
                return None
            return 0.0, False
        o = self.owner.get(q)
        if o is not None and o != net:
            a = self.axis.get(q, 0)
            if q in self.vertex or a & _bit(d) or a == (_H | _V):
                return None
            return self.k.cross, True
        return self.soft.get(q, 0.0), False

    def _branches(self, q: Cell) -> int:
        return bin(self.links.get(q, 0)).count("1") + (1 if q in self.pin_at else 0)

    def _port_cells(self, q: Cell, d: int, name: str) -> list[Cell]:
        half = max(1, math.ceil(50 * len(name) / 2 / GRID))
        dx, dy = DIRS[d]
        rows = [(q[0] + dx * i, q[1] + dy * i) for i in (1, 2, 3)]
        return [(rx + j, ry) for (rx, ry) in rows for j in range(-half, half + 1)]

    def _port_fits(self, net: str, q: Cell, d: int) -> bool:
        # The symbol reaches back over its own hotspot too: not on a text.
        return q not in self.soft and all(self._free(a) for a in self._port_cells(q, d, net))

    # --- search ------------------------------------------------------------

    def _search(self, net: str, src: Cell, src_dir: int, port_dir: Optional[int],
                port_cost: float, label_cost: Optional[float] = None):
        """Cheapest way from a pin to its net's wire, to a free spot for a
        power symbol (a rail), or to a stub with room for a net label (a
        signal). Returns (cost, cells, "tree" | "port" | "label") or None."""
        tree = self.tree.get(net, set())
        if tree:
            tx0 = min(q[0] for q in tree)
            tx1 = max(q[0] for q in tree)
            ty0 = min(q[1] for q in tree)
            ty1 = max(q[1] for q in tree)
        has_port = port_dir is not None

        def h(q: Cell) -> float:
            hb = (max(tx0 - q[0], 0, q[0] - tx1) + max(ty0 - q[1], 0, q[1] - ty1)) \
                if tree else INF
            if has_port:
                hb = min(hb, port_cost)
            if label_cost is not None:
                hb = min(hb, label_cost)
            return hb

        best: Optional[tuple[float, tuple, Cell, str]] = None
        if has_port and src_dir == port_dir and self._port_fits(net, src, port_dir):
            best = (port_cost, (src, -1), src, "port_here")
        # A route dearer than naming the pin with a label is not worth
        # finding: give up there instead of searching the whole sheet.
        h0 = h(src)
        limit = (2 * h0 if h0 < INF else 0) + self.k.label_fallback + 20
        start = (src, -1)
        g = {start: 0.0}
        parent: dict[tuple, Optional[tuple]] = {start: None}
        heap = [(h(src), 0.0, src, -1)]
        back = (src_dir + 2) % 4
        while heap:
            f, gc, q, d = heapq.heappop(heap)
            if best is not None and f >= best[0] or f > limit:
                break
            if gc > g.get((q, d), INF):
                continue
            crossing_here = d != -1 and self.owner.get(q) not in (None, net)
            for nd in range(4):
                if d == -1:
                    if nd == back:
                        continue
                    turn = 0.0 if nd == src_dir else self.k.off_pin_axis
                else:
                    if nd == (d + 2) % 4 or (crossing_here and nd != d):
                        continue
                    turn = 0.0 if nd == d else self.k.bend
                n = (q[0] + DIRS[nd][0], q[1] + DIRS[nd][1])
                step = self.k.step + turn
                if n in tree:
                    if crossing_here or self._branches(n) >= 3:
                        continue
                    join = self.k.junction if self._branches(n) == 2 else 0.0
                    if n in self.pin_at and self._branches(n) >= 2:
                        join = self.k.junction_at_pin
                    total = gc + step + join
                    if best is None or total < best[0]:
                        best = (total, (q, d), n, "tree")
                    continue
                ent = self._enter(net, n, nd)
                if ent is None:
                    continue
                extra, crossing = ent
                ng = gc + step + extra
                if has_port and nd == port_dir and not crossing and n not in self.pin_at \
                        and self._port_fits(net, n, port_dir):
                    total = ng + port_cost
                    if best is None or total < best[0]:
                        best = (total, (q, d), n, "port")
                if label_cost is not None and nd in (0, 2) and not crossing \
                        and n not in self.pin_at and n not in self.owner \
                        and n not in self.soft and self._label_fits(n, net):
                    total = ng + label_cost
                    if best is None or total < best[0]:
                        best = (total, (q, d), n, "label")
                key = (n, nd)
                if ng < g.get(key, INF):
                    g[key] = ng
                    parent[key] = (q, d)
                    heapq.heappush(heap, (ng + h(n), ng, n, nd))
        if best is None:
            return None
        cost, last, end, kind = best
        if kind == "port_here":
            return cost, [src], "port"
        cells = [end]
        s: Optional[tuple] = last
        while s is not None:
            cells.append(s[0])
            s = parent.get(s)
        cells.reverse()
        return cost, cells, kind

    # --- drawing -----------------------------------------------------------

    def _anchor(self, net: str, q: Cell):
        for ref, num, _, n in self.pin_at.get(q, []):
            if n == net:
                return f"{ref}.{num}"
        return [q[0] * GRID, q[1] * GRID]

    def _commit(self, net: str, cells: list[Cell]) -> None:
        tree = self.tree.setdefault(net, set())
        if len(cells) == 1:
            tree.add(cells[0])
            return
        corners = [cells[0]]
        for i in range(1, len(cells)):
            a, b = cells[i - 1], cells[i]
            d = next(k for k, v in DIRS.items() if (a[0] + v[0], a[1] + v[1]) == b)
            for q, dd in ((a, d), (b, (d + 2) % 4)):
                self.axis[q] = self.axis.get(q, 0) | _bit(d)
                if self.owner.get(q, net) == net:
                    self.links[q] = self.links.get(q, 0) | (1 << dd)
            if i < len(cells) - 1:
                c2 = cells[i + 1]
                if (c2[0] - b[0], c2[1] - b[1]) != DIRS[d]:
                    corners.append(b)
                    self.out.bends += 1
        corners.append(cells[-1])
        for q in cells:
            o = self.owner.get(q)
            if o is None or o == net:
                self.owner[q] = net
                tree.add(q)
            else:
                self.out.crossings += 1
                self.crossed.setdefault(net, set()).add(q)
                self.tangled.update((net, o))
        self.vertex.update(corners)
        self.out.length += len(cells) - 1
        path = [self._anchor(net, corners[0])] + \
            [[q[0] * GRID, q[1] * GRID] for q in corners[1:-1]] + \
            [self._anchor(net, corners[-1])]
        self.out.wires.append({"net": net, "path": path})

    def _place_port(self, net: str, q: Cell, d: int, style: str) -> None:
        for a in self._port_cells(q, d, net):
            self.reserved[a] = net
        self.reserved[q] = net
        at = self._anchor(net, q)
        port = {"net": net, "at": at, "style": style}
        if d == DOWN and style != "gnd_power":
            port["orientation"] = 3
        self.out.ports.append(port)
        self.tree.setdefault(net, set()).add(q)

    def _label(self, net: str, q: Cell) -> None:
        self.out.labels.append({"net": net, "at": [q[0] * GRID, q[1] * GRID]})
        self.named.setdefault(net, set()).add(q)
        for a in self._label_cells(q, net):
            self.reserved[a] = net
        self.reserved.setdefault(q, net)

    def _label_cells(self, q: Cell, net: str) -> list[Cell]:
        n = math.ceil(50 * len(net) / GRID)
        return [(q[0] + i, q[1] + 1) for i in range(0, n + 1)]

    def _label_fits(self, q: Cell, net: str) -> bool:
        return all(self._free(a) for a in self._label_cells(q, net))

    # --- nets --------------------------------------------------------------

    def _pin_order(self, net_name: str, attached: set[str]) -> list[tuple[str, str]]:
        net = self.c.nets[net_name]
        pos = {}
        for ref, num in net.pins:
            pe = next(p for p in self.lay.parts[ref].pins if p.number == num)
            pos[(ref, num)] = (pe.x, pe.y)
        return sorted(net.pins, key=lambda rn: (rn[0] in attached, pos[rn][0], -pos[rn][1]))

    def _pin_cell(self, ref: str, num: str) -> tuple[Cell, int]:
        pe = next(p for p in self.lay.parts[ref].pins if p.number == num)
        return (pe.x // GRID, pe.y // GRID), pe.orientation

    def route_net(self, net_name: str, attached: set[str]) -> None:
        net = self.c.nets[net_name]
        port_dir = net.port_dir
        port_cost = self.k.port_ground if net.kind == "ground" else self.k.port_power
        for i, (ref, num) in enumerate(self._pin_order(net_name, attached)):
            q, o = self._pin_cell(ref, num)
            tree = self.tree.setdefault(net_name, set())
            if q in tree:
                continue
            if port_dir is None and not tree:
                tree.add(q)                     # the first pin roots the net
                continue
            found = self._search(net_name, q, o, port_dir, port_cost,
                                 self.k.label_pin if port_dir is None else None)
            if found is None:
                self._fallback(net_name, q, o, ref, num)
                continue
            cost, cells, kind = found
            self.out.cost += cost
            if kind == "port":
                if len(cells) > 1:
                    self._commit(net_name, cells)
                self._place_port(net_name, cells[-1], port_dir, net.port_style)
            elif kind == "label":
                self._commit(net_name, cells)
                self._label(net_name, cells[-1])
            else:
                self._commit(net_name, cells)
        if port_dir is None:
            self._name(net_name)

    def _fallback(self, net: str, q: Cell, o: int, ref: str, num: str) -> None:
        """No route: name the pin instead (a stub and a label, or a symbol)."""
        self.out.fallbacks.append(f"{ref}.{num} ({net})")
        self.out.cost += self.k.label_fallback
        port_dir = self.c.nets[net].port_dir
        if port_dir is not None:
            self._place_port(net, q, port_dir, self.c.nets[net].port_style)
            return
        self.tree.setdefault(net, set()).add(q)
        self._labels_off(net, {q})

    def _components(self, net: str) -> list[set[Cell]]:
        cells = set(self.tree.get(net, set()))
        seen: set[Cell] = set()
        out = []
        for start in sorted(cells):
            if start in seen:
                continue
            comp = {start}
            todo = [start]
            seen.add(start)
            while todo:
                q = todo.pop()
                links = self.links.get(q, 0) if self.owner.get(q) == net else 0
                for d in range(4):
                    if links & (1 << d):
                        n = (q[0] + DIRS[d][0], q[1] + DIRS[d][1])
                        while n in self.crossed.get(net, ()):   # over a crossing
                            n = (n[0] + DIRS[d][0], n[1] + DIRS[d][1])
                        if n in cells and n not in seen:
                            seen.add(n)
                            comp.add(n)
                            todo.append(n)
            out.append(comp)
        return out

    def _name(self, net: str) -> None:
        for comp in self._components(net):
            if comp & self.named.get(net, set()):
                continue                       # already named (a fallback's label)
            self._labels_off(net, comp)

    def _labels_off(self, net: str, comp: set[Cell]) -> None:
        """One label on a horizontal stretch of this piece of the net, or on a
        short stub off it when no stretch has room for the text."""
        spots = []
        for q in comp:
            if self.owner.get(q) != net or q in self.pin_at:
                continue
            if self.axis.get(q, 0) != _H or self._branches(q) > 2:
                continue
            if self._label_fits(q, net):
                spots.append((0, -q[1], q[0], q))
        if spots:
            self._label(net, min(spots)[3])
            return
        for q in sorted(comp):
            for d in (0, 2):
                # A stub joins the piece as a T at most (never a four-way),
                # and only where the cell's own wire runs across it.
                if self._branches(q) >= 3 or (q in self.pin_at and self._branches(q) >= 2):
                    continue
                if self.links.get(q, 0) & (1 << d):
                    continue
                path = [q]
                for i in (1, 2, 3):
                    n = (q[0] + DIRS[d][0] * i, q[1] + DIRS[d][1] * i)
                    ent = self._enter(net, n, d)
                    if ent is None or ent[1] or n in self.pin_at or n in self.owner:
                        break
                    path.append(n)
                    if self._label_fits(n, net):
                        self._commit(net, path)
                        self.out.cost += self.k.label_stub
                        self._label(net, n)
                        return
        # Nowhere with room: on the first pin, text unchecked.
        q = min(comp)
        self.out.cost += self.k.label_fallback
        self.out.labels.append({"net": net, "at": self._anchor(net, q)})
        self.named.setdefault(net, set()).add(q)


def route(circuit: Circuit, layout: Layout, attached: set[str],
          costs: Optional[Costs] = None) -> Routed:
    """Route every net: signals first, shortest first, then rails, then
    ground. When nets cross, route once more with the crossing nets first
    (rip-up and reroute) and keep the cheaper result."""
    first = Router(circuit, layout, costs)

    def span(name: str) -> int:
        pts = [first._pin_cell(ref, num)[0] for ref, num in circuit.nets[name].pins]
        return (max(p[0] for p in pts) - min(p[0] for p in pts)
                + max(p[1] for p in pts) - min(p[1] for p in pts))

    rank = {"signal": 0, "power": 1, "ground": 2}
    order = sorted(circuit.nets, key=lambda n: (rank[circuit.nets[n].kind], span(n), n))
    # A net with one pin on this sheet still gets its name (a label or a
    # symbol): its other pins are on another sheet.
    for name in order:
        first.route_net(name, attached)
    if not first.tangled:
        return first.out
    again = Router(circuit, layout, costs)
    tangled_first = sorted(order, key=lambda n: n not in first.tangled)   # stable
    for name in tangled_first:
        again.route_net(name, attached)
    return again.out if again.out.cost < first.out.cost else first.out
